var kindOf = (f) => {
	const n = f.name.toLowerCase();
	if (f.type === "application/pdf" || n.endsWith(".pdf")) return "pdf";
	if (n.endsWith(".docx")) return "docx";
	if (/^image\/(png|jpeg|webp)$/.test(f.type) || /\.(png|jpe?g|webp)$/.test(n)) return "image";
	return "";
};
